'use client'

import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase'
import { getTBAData, TBATeam } from '@/lib/tba'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Loader2, MapPin, Globe, CheckCircle2, Gauge, Weight, ArrowUpCircle, Zap, Shield, Settings } from 'lucide-react'
import { Badge } from '@/components/ui/badge'

interface PitData {
    id: string
    team_number: number
    event_key: string
    robot_weight: number
    fuel_capacity: number
    top_speed: number
    fuel_per_second: number
    primary_role: string
    climb_level: number
    climbs_in_auto: boolean
    obstacle_handling: string
    drive_train_type: string
    comments: string
    tba_info?: TBATeam
}

export default function PitScoutingList() {
    const [pitData, setPitData] = useState<PitData[]>([])
    const [loading, setLoading] = useState(true)
    const [selectedTeam, setSelectedTeam] = useState<string>('all')

    const supabase = createClient()

    useEffect(() => {
        async function fetchData() {
            setLoading(true)
            const { data, error } = await supabase
                .from('pit_scouting')
                .select('*')
                .order('team_number', { ascending: true })

            if (error) {
                console.error('Error fetching pit data:', error)
                setLoading(false)
                return
            }

            const extendedData = [...(data || [])] as PitData[]

            const fetchTba = async () => {
                const promises = extendedData.map(async (item) => {
                    try {
                        const tba = await getTBAData(`/team/frc${item.team_number}`)
                        item.tba_info = tba
                    } catch (e) {
                        console.warn(`Could not fetch TBA info for ${item.team_number}`)
                    }
                })
                await Promise.all(promises)
                setPitData(extendedData)
                setLoading(false)
            }

            fetchTba()
        }

        fetchData()
    }, [])

    const filteredData = selectedTeam === 'all'
        ? pitData
        : pitData.filter(d => d.team_number.toString() === selectedTeam)

    if (loading) {
        return <div className="flex justify-center p-8"><Loader2 className="h-8 w-8 animate-spin text-primary" /></div>
    }

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-muted/20 p-6 rounded-2xl border">
                <div className="space-y-1">
                    <h2 className="text-2xl font-black tracking-tight">Technical Specifications</h2>
                    <p className="text-sm text-muted-foreground font-medium">Static data from Pit Scouting</p>
                </div>
                <Select value={selectedTeam} onValueChange={(val) => setSelectedTeam(val || 'all')}>
                    <SelectTrigger className="w-full md:w-[220px] h-11 border-2">
                        <SelectValue placeholder="All Teams" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">View All Teams</SelectItem>
                        {Array.from(new Set(pitData.map(d => d.team_number))).map((teamNum) => (
                            <SelectItem key={teamNum} value={teamNum.toString()}>Team {teamNum}</SelectItem>
                        ))}
                    </SelectContent>
                </Select>
            </div>

            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                {filteredData.map((robot) => (
                    <Card key={robot.id} className="overflow-hidden border-2 hover:border-primary transition-all group">
                        <CardHeader className="bg-primary/5 pb-4 border-b">
                            <div className="flex justify-between items-start">
                                <div>
                                    <div className="flex items-center gap-2">
                                        <CardTitle className="text-3xl font-black">#{robot.team_number}</CardTitle>
                                        {robot.tba_info && <CheckCircle2 className="h-4 w-4 text-primary" />}
                                    </div>
                                    <p className="text-sm font-bold text-primary italic">
                                        {robot.tba_info?.nickname || 'Unknown'}
                                    </p>
                                </div>
                                <Badge variant="secondary" className="bg-primary/10 text-primary border-primary/20 text-[10px] font-black tracking-widest uppercase py-1 px-3">
                                    {robot.event_key}
                                </Badge>
                            </div>
                        </CardHeader>
                        <CardContent className="pt-6 space-y-6">
                            {/* Stats Grid */}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="p-3 rounded-xl bg-muted/30 border space-y-1">
                                    <div className="text-[10px] font-black text-muted-foreground uppercase flex items-center gap-2">
                                        <Weight className="h-3 w-3" /> Weight
                                    </div>
                                    <div className="text-lg font-black">{robot.robot_weight || '0'} lb</div>
                                </div>
                                <div className="p-3 rounded-xl bg-muted/30 border space-y-1">
                                    <div className="text-[10px] font-black text-muted-foreground uppercase flex items-center gap-2">
                                        <Gauge className="h-3 w-3" /> Top Speed
                                    </div>
                                    <div className="text-lg font-black">{robot.top_speed || '0'} <span className="text-[10px]">ft/s</span></div>
                                </div>
                                <div className="p-3 rounded-xl bg-muted/30 border space-y-1">
                                    <div className="text-[10px] font-black text-muted-foreground uppercase flex items-center gap-2">
                                        <Zap className="h-3 w-3" /> Rate
                                    </div>
                                    <div className="text-lg font-black">{robot.fuel_per_second || '0'} <span className="text-[10px]">f/sec</span></div>
                                </div>
                                <div className="p-3 rounded-xl bg-muted/30 border space-y-1">
                                    <div className="text-[10px] font-black text-muted-foreground uppercase flex items-center gap-2">
                                        <ArrowUpCircle className="h-3 w-3" /> Climb
                                    </div>
                                    <div className="text-lg font-black">Level {robot.climb_level || '?'}</div>
                                </div>
                            </div>

                            {/* Secondary Details */}
                            <div className="space-y-3 pt-2">
                                <div className="flex items-center justify-between text-xs">
                                    <span className="font-extrabold text-muted-foreground uppercase tracking-widest">Drive Train</span>
                                    <Badge variant="outline" className="font-black border-2">{robot.drive_train_type}</Badge>
                                </div>
                                <div className="flex items-center justify-between text-xs">
                                    <span className="font-extrabold text-muted-foreground uppercase tracking-widest">Role</span>
                                    <Badge className="font-black">{robot.primary_role}</Badge>
                                </div>
                                <div className="flex items-center justify-between text-xs">
                                    <span className="font-extrabold text-muted-foreground uppercase tracking-widest">Pathing</span>
                                    <span className="font-black text-primary italic uppercase">{robot.obstacle_handling}</span>
                                </div>
                            </div>

                            {robot.comments && (
                                <div className="bg-muted/30 p-4 rounded-xl border border-dashed relative">
                                    <div className="text-[9px] font-black absolute -top-2 left-3 bg-background px-2 border rounded uppercase">Notes</div>
                                    <p className="text-xs italic text-muted-foreground leading-relaxed">
                                        "{robot.comments}"
                                    </p>
                                </div>
                            )}
                        </CardContent>
                    </Card>
                ))}
            </div>
        </div>
    )
}
